@If(DueDate = "";@Return(@Do(@Command([EditGotoField];"DueDate");@Prompt([Ok];"Missing Value";"Please select the Response required by before proceeding")));"");
@If (@Date(DueDate) <= @Date(@Year(@Today);@Month(@Today);@Day(@Today));@Return(@Do(@Command([EditGotoField];"DueDate") ;@Prompt([Ok];"Error"; "Invalid date selection!! Response required by must be greater than today date!")));"");
@If (PNC1 = "" & PPA1 = "" & PNC2 = "" & PPA2 = "" & PNC3 = "" & PPA3 = "" & PNC4 = "" & PPA4 = "" & PNC5 = "" & PPA5 = "" & PNC6 = "" & PPA6 = "";@Return(@Do(@Command([EditGotoField];"PNC1") ;@Prompt([Ok];"Missing Value"; "At least one Potential Non-Conformance Description must be entered before proceeding!")));"");

@If ((PNC1 = "" & PPA1 = "") | (PNC1 != "" & PPA1 != "");"";@Return(@Do(@Command([EditGotoField];"PNC1") ;@Prompt([Ok];"Missing Value"; "All data must be filled in Potential Non-Conformance Description - Line No 1"))));
@If ((PNC2 = "" & PPA2 = "") | (PNC2 != "" & PPA2 != "");"";@Return(@Do(@Command([EditGotoField];"PNC2") ;@Prompt([Ok];"Missing Value"; "All data must be filled in Potential Non-Conformance Description - Line No 2"))));
