FIELD IssuedDate := @Today;
FIELD CurrentAction := "Reply";

@SetField("NextReminder";DueDate);

@Command([ViewRefreshFields]);
@Command([FileSave]);
@If(CurrentAction="Reply";@SetField("temp";PARNo);"");

@If (temp = "";"";@MailSend(PARRecipient;@UserName:MailingList1;NULL;"PAR (Request) : " + temp;NULL;"Please click the doclink to open the PAR ---> ";[IncludeDoclink]));

